WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_e_tool'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '工具增减', 'kp-eng-e-tool', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "工具/机器增减"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "机器其实就是不会累的工人。本质等同于人数变化。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "特征词：“原有 5 台抽水机，2 小时后坏了 1 台……”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "完全照搬“单位人天法”。令 1台机器1小时的工作量为 1。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[机器数量发生损毁或增加] --> B[令 1台机器单位效率 = 1]\nB --> C[W = 机器总数 × 计划运转时间]\nC --> D[分段减去正常运转时期消耗的 W]\nD --> E[剩余 W ÷ 现在的机器可用数量 = 延后或提前的实际时间]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 8 台挖掘机计划工作 10 小时挖完。工作 2 小时后，有 2 台突发故障报废。问实际完成任务比计划晚了多少小时？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋效率：1 台机器效率为 1。W = 8 × 10 = 80。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "前 2 小时：8 台齐开，完成 8 × 2 = 16。剩余 80 - 16 = 64。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "故障后：坏了 2 台，剩 6 台。剩余时间 = 64 ÷ 6 = 10.67 小时。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比对计划：计划剩下 8 小时，现在用了 10.67 小时。晚了 2.67 小时。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略不同型号的机器：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果题目说“增加了 2 台 B型 机器”，此时就不能简单当成“人头加2”了，必须先算出 A型 和 B型 机器的效率比（参考效率比求解法），再按各自的效率相加！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "机器题和人工题是同构的，遇到机器题直接在脑子里替换成“几个工人罢工了”，逻辑立刻顺畅。"}]}]}$$ AS jsonb), NULL, '工具增减的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "工具增减"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_e_tool", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
